        lines.append("  ".join("-" * w for w in widths))
        lines += ["  ".join(v.ljust(w) for v, w in zip(row, widths)) for row in cells]
        if self._nrows > max_rows:
            lines.append(f"... ({self._nrows - max_rows} more rows)")
        return "\n".join(lines)
